//! SDK E2E — the same acceptance chain as `tests/mock_e2e.rs`, but against
//! the **real engine** (`SdkBackend`, feature `sdk`):
//!
//! import → place on a track → split → trim → ripple_delete →
//! `render.get_frame` (PNG) → pixel assertions on the decoded frame →
//! undo the whole chain → the timeline serialisation equals the initial
//! snapshot.
//!
//! The media is generated by the engine's own encoder at run time, so the
//! test needs no binary fixture in the repository: a solid-colour H.264 clip
//! is written to a temp file, imported through the SDK, and the rendered
//! frame is checked against the *codec-tolerant* expectation (dominant
//! channel + non-black coverage + determinism), never against a hard-coded
//! pixel hash — H.264 + 4:2:0 quantisation makes an exact hash meaningless
//! across encoder versions.
//!
//! Everything goes through `dispatch::execute`, i.e. through schema
//! validation and one engine undo group per call, exactly like the mock
//! path.
//!
//! The engine's undo stack is process-wide, so the tests here take a mutex.

#![cfg(feature = "sdk")]

use std::path::{Path, PathBuf};
use std::sync::{Mutex, MutexGuard};

use oak_ai_tools::dispatch::execute;
use oak_ai_tools::render::Frame;
use oak_ai_tools::sdk::SdkBackend;
use oak_ai_tools::timecode::Rat;
use oak_engine_rust_sdk::codec::{
	Codec, EncodingParams, EncoderSession, Format, Frame as SdkFrame,
};
use oak_engine_rust_sdk::types::{PixelFormat, Rational, VideoParams};
use serde_json::{Value, json};

/// Serialises the E2E tests: the engine's undo stack is process-global.
static ENGINE: Mutex<()> = Mutex::new(());

fn engine_lock() -> MutexGuard<'static, ()> {
	ENGINE.lock().unwrap_or_else(|error| error.into_inner())
}

fn call(backend: &mut SdkBackend, tool: &str, args: Value) -> Value {
	execute(backend, tool, args).unwrap_or_else(|err| panic!("{tool} failed: {err:?}"))
}

/// Writes a solid-colour H.264 clip with the engine's own encoder.
fn encode_solid_clip(
	path: &Path,
	colour: [f32; 3],
	frames: i32,
	fps: i32,
	size: i32,
) {
	let mut params = EncodingParams::new();
	params
		.set_filename(path.to_str().expect("utf-8 temp path"))
		.expect("encoder filename");
	params.format = Format::MPEG4Video as i32;
	params.video_enabled = 1;
	params.video_codec = Codec::H264 as i32;
	params.video_width = size;
	params.video_height = size;
	params.video_time_base_num = 1;
	params.video_time_base_den = fps;
	params.video_pixel_format = PixelFormat::F32 as i32;
	params.video_pixel_aspect_num = 1;
	params.video_pixel_aspect_den = 1;

	let session = EncoderSession::create(&params).expect("an H.264 encoder");
	session.open().expect("open the encoder");
	let mut video = VideoParams::new();
	video.width = size;
	video.height = size;
	video.format = PixelFormat::F32 as i32;
	video.channel_count = 4;
	video.frame_rate_num = fps;
	video.frame_rate_den = 1;
	video.time_base_num = 1;
	video.time_base_den = fps;

	for index in 0..frames {
		let mut frame = SdkFrame::with_params(&video);
		frame.allocate().expect("allocate the frame");
		{
			let data = frame.data().expect("frame buffer");
			// F32 RGBA: the buffer is `width * height * 4` little-endian f32.
			let floats = unsafe {
				std::slice::from_raw_parts_mut(
					data.as_mut_ptr() as *mut f32,
					data.len() / std::mem::size_of::<f32>(),
				)
			};
			for pixel in floats.chunks_exact_mut(4) {
				pixel[0] = colour[0];
				pixel[1] = colour[1];
				pixel[2] = colour[2];
				pixel[3] = 1.0;
			}
		}
		frame.set_timestamp(Rational::new(i64::from(index), i64::from(fps)));
		session.write_video(&frame).expect("write a frame");
	}
	session.flush().expect("flush the encoder");
	session.close().expect("close the encoder");
}

/// A temp media path unique to this test binary.
fn temp_media(tag: &str) -> PathBuf {
	let path = std::env::temp_dir().join(format!(
		"oak_sdk_e2e_{tag}_{}.mp4",
		std::process::id()
	));
	let _ = std::fs::remove_file(&path);
	path
}

/// The decoded frame of a `render.get_frame` result (PNG path).
fn frame_of(out: &Value) -> Frame {
	let png = out["png_base64"].as_str().expect("png payload");
	let bytes = b64_decode(png);
	Frame::from_png(&bytes).expect("the engine's PNG decodes")
}

/// A frame's mean RGB as `[r, g, b]`.
fn mean_rgb(frame: &Frame) -> [f64; 3] {
	frame.stats().mean
}

/// The rational a JSON `{num, den}` payload carries.
fn rat_of(value: &Value) -> Rat {
	let num = value["num"]
		.as_i64()
		.unwrap_or_else(|| panic!("rational numerator: {value}"));
	let den = value["den"].as_i64().expect("rational denominator");
	Rat::new(num, den).expect("a valid rational")
}

#[test]
fn acceptance_chain_render_and_full_undo_on_the_engine() {
	let _guard = engine_lock();
	let media_a = temp_media("a");
	let media_b = temp_media("b");
	// 2 s each at 10 fps: enough room to split at 1 s and trim to 1.5 s.
	encode_solid_clip(&media_a, [0.85, 0.10, 0.10], 20, 10, 64);
	encode_solid_clip(&media_b, [0.10, 0.15, 0.85], 20, 10, 64);
	assert!(media_a.exists() && media_b.exists(), "media was generated");

	let mut backend = SdkBackend::new();

	// --- open ---------------------------------------------------------
	// `project.open` initialises the render manager (inline backend) and the
	// process-wide active project, then creates the default sequence.
	let out = call(&mut backend, "project.open", json!({"name": "e2e", "fps": 30}));
	assert_eq!(out["created"], true);
	assert_eq!(out["backend"], "sdk");
	assert_eq!(out["project"]["fps"], json!({"num": 30, "den": 1}));
	let sequence = call(&mut backend, "project.get_overview", json!({}))["active_sequence"]
		.as_str()
		.expect("active sequence id")
		.to_string();

	// --- probe + import -----------------------------------------------
	let probe = call(
		&mut backend,
		"media.probe",
		json!({"path": media_a.display().to_string()}),
	);
	assert_eq!(probe["exists"], true);
	assert_eq!(probe["width"], 64);
	assert_eq!(probe["height"], 64);
	assert_eq!(probe["fps"], json!({"num": 10, "den": 1}));
	// The container duration is the encoder's own arithmetic; require the
	// right ballpark instead of one exact fraction.
	// Pins the documented fallback: the SDK's probe reports no container
	// duration for this file, so the backend falls back to the video stream's
	// `duration x time base` and says so. If the SDK ever starts reporting a
	// container duration this assertion fails loudly instead of the fallback
	// silently changing.
	assert_eq!(probe["duration_source"], "video stream time base");
	let probed = rat_of(&probe["duration"]);
	assert!(probed > Rat::new(3, 2).unwrap(), "probed duration {probed}");
	assert!(probed <= Rat::new(5, 2).unwrap(), "probed duration {probed}");

	let out = call(
		&mut backend,
		"media.import_footage",
		json!({"paths": [media_a.display().to_string(), media_b.display().to_string()]}),
	);
	assert_eq!(out["footage"].as_array().unwrap().len(), 2);
	assert_eq!(out["failed"].as_array().unwrap().len(), 0);
	let footage_a = out["footage"][0]["id"].as_str().unwrap().to_string();
	let footage_b = out["footage"][1]["id"].as_str().unwrap().to_string();
	let duration = rat_of(&out["footage"][0]["duration"]);
	// The clip runs to the end of the footage, so the whole chain below is
	// expressed against this value rather than a hard-coded 2 s.
	assert!(
		duration > Rat::new(3, 2).unwrap() && duration <= Rat::new(2, 1).unwrap(),
		"the imported footage duration must cover the edit chain, got {duration}"
	);

	// --- a track ------------------------------------------------------
	let out = call(
		&mut backend,
		"timeline.add_track",
		json!({"type": "video", "sequence": sequence}),
	);
	let track = out["track"].as_str().unwrap().to_string();
	assert_eq!(out["type"], "video");

	// --- place both clips ---------------------------------------------
	let out = call(
		&mut backend,
		"timeline.place_clip",
		json!({"track": track, "footage": footage_a, "in": 0}),
	);
	let clip_a = out["clip"].as_str().unwrap().to_string();
	assert_eq!(out["in"], json!({"num": 0, "den": 1}));
	assert_eq!(out["out"], duration.to_json());
	assert_eq!(out["length"], duration.to_json());
	let out = call(
		&mut backend,
		"timeline.place_clip",
		// `2` would be a *frame index* (2/30 s); the second clip starts at 2 s.
		json!({"track": track, "footage": footage_b, "in": {"num": 2, "den": 1}}),
	);
	let clip_b = out["clip"].as_str().unwrap().to_string();
	assert_eq!(out["in"], json!({"num": 2, "den": 1}));

	// The timeline as it stands after import + placement is the snapshot the
	// full undo must restore.
	let initial = backend.serialize_timeline().expect("timeline snapshot");

	// --- render before the edits: t=1 s is inside clip A --------------
	let red = call(
		&mut backend,
		"render.get_frame",
		json!({
			"sequence": sequence,
			"time": {"num": 1, "den": 1},
			"format": "png",
			"max_size": {"width": 96, "height": 96},
		}),
	);
	assert_eq!(red["backend"], "sdk");
	assert_eq!(red["width"], 96);
	assert_eq!(red["height"], 96);
	let red_frame = frame_of(&red);
	assert_eq!(red_frame.width, 96);
	assert_eq!(red_frame.height, 96);
	let red_mean = mean_rgb(&red_frame);
	// Solid red footage through H.264: the red channel dominates and the
	// frame is fully covered (a gap would be transparent black).
	assert!(
		red_mean[0] > 0.4,
		"the red footage must dominate the red channel, got {red_mean:?}"
	);
	assert!(
		red_mean[0] > red_mean[2] + 0.2,
		"red must be clearly above blue, got {red_mean:?}"
	);
	assert!(
		red_frame.stats().non_black_ratio > 0.99,
		"the frame must be covered by footage, got {}",
		red_frame.stats().non_black_ratio
	);

	// --- split clip A at 1 s ------------------------------------------
	let out = call(
		&mut backend,
		"timeline.split_clip",
		json!({"clip": clip_a, "time": {"num": 1, "den": 1}}),
	);
	let right = out["new_clip"].as_str().unwrap().to_string();
	assert_ne!(right, clip_a);
	assert_eq!(out["time"], json!({"num": 1, "den": 1}));

	// --- trim the right half's in point to 1.5 s -----------------------
	let out = call(
		&mut backend,
		"timeline.trim_clip",
		json!({"clip": right, "side": "in", "time": {"num": 3, "den": 2}}),
	);
	assert_eq!(out["in"], json!({"num": 3, "den": 2}));
	assert_eq!(out["out"], duration.to_json());
	assert_eq!(
		out["length"],
		duration.checked_sub(Rat::new(3, 2).unwrap()).unwrap().to_json()
	);
	// The split advanced the media in point to 1 s (the media split point),
	// and the trim moves it by the same 0.5 s the head moved.
	assert_eq!(out["media_in"], json!({"num": 3, "den": 2}));

	// --- ripple_delete the left half ----------------------------------
	let out = call(&mut backend, "timeline.ripple_delete", json!({"clip": clip_a}));
	assert_eq!(out["removed"], true);
	assert_eq!(out["ripple"], json!({"num": 1, "den": 1}));

	// The right half moved from [1.5, 2) to [0.5, 1) and clip B from
	// [2, 4) to [1, 3) — read back from the document, not from our wish.
	let overview = call(&mut backend, "project.get_overview", json!({}));
	let clips = overview["sequences"][0]["tracks"]
		.as_array()
		.unwrap()
		.iter()
		.find(|entry| entry["id"] == json!(track))
		.expect("the track in the overview")["clips"]
		.clone();
	let clips = clips.as_array().unwrap();
	let moved = clips
		.iter()
		.find(|clip| clip["id"] == json!(right))
		.expect("the trimmed half on the track");
	assert_eq!(moved["in"], json!({"num": 1, "den": 2}));
	assert_eq!(moved["out"], duration.checked_sub(Rat::new(1, 1).unwrap()).unwrap().to_json());
	let shifted = clips
		.iter()
		.find(|clip| clip["id"] == json!(clip_b))
		.expect("clip B on the track");
	// Clip B was placed at 2 s and the ripple closed the 1 s gap before it.
	assert_eq!(shifted["in"], json!({"num": 1, "den": 1}));
	assert_eq!(
		shifted["out"],
		Rat::new(1, 1).unwrap().checked_add(duration).unwrap().to_json()
	);

	// --- render after the edits ---------------------------------------
	// t = 0.75 s is now inside the moved right half (red footage)...
	let out = call(
		&mut backend,
		"render.get_frame",
		json!({
			"sequence": sequence,
			"time": {"num": 3, "den": 4},
			"format": "png",
			"max_size": {"width": 96, "height": 96},
		}),
	);
	let after_split = frame_of(&out);
	// ... and t = 1.25 s is inside clip B (blue footage).
	let out = call(
		&mut backend,
		"render.get_frame",
		json!({
			"sequence": sequence,
			"time": {"num": 5, "den": 4},
			"format": "png",
			"max_size": {"width": 96, "height": 96},
		}),
	);
	let blue = frame_of(&out);
	let blue_mean = mean_rgb(&blue);
	assert!(
		blue_mean[2] > 0.4 && blue_mean[2] > blue_mean[0] + 0.2,
		"the blue footage must dominate the blue channel, got {blue_mean:?}"
	);
	// The two clips are distinguishable, i.e. the frame really follows the
	// timeline after the split/trim/ripple chain.
	let after_mean = mean_rgb(&after_split);
	assert!(
		after_mean[0] > after_mean[2] + 0.2,
		"after the edits t=0.75 s must still show the red clip, got {after_mean:?}"
	);
	assert!(
		(after_mean[0] - blue_mean[0]).abs() > 0.3,
		"the two clips must not render the same frame ({after_mean:?} vs {blue_mean:?})"
	);

	// --- determinism (the golden-frame invariant, no binary fixture) ---
	let repeat = call(
		&mut backend,
		"render.get_frame",
		json!({
			"sequence": sequence,
			"time": {"num": 1, "den": 1},
			"format": "png",
			"max_size": {"width": 96, "height": 96},
		}),
	);
	// t = 1 s is now the seam: the moved right half ends exactly at 1 s, so
	// the frame at that instant belongs to clip B.  Re-rendering the same
	// time must produce the identical hash.
	let repeat_again = call(
		&mut backend,
		"render.get_frame",
		json!({
			"sequence": sequence,
			"time": {"num": 1, "den": 1},
			"format": "png",
			"max_size": {"width": 96, "height": 96},
		}),
	);
	assert_eq!(
		repeat["fnv64"], repeat_again["fnv64"],
		"the same render call must be deterministic"
	);
	assert_eq!(repeat["mean_rgb"], repeat_again["mean_rgb"]);

	// --- undo the whole chain -----------------------------------------
	// Every transactional tool call is one engine undo step; the read-only
	// calls (probe/overview/render) commit empty groups, which the engine
	// discards, so undo only has to walk the edits back.
	let mut guard = 0;
	while backend.serialize_timeline().expect("snapshot") != initial {
		let _ = call(&mut backend, "edit.undo", json!({}));
		guard += 1;
		assert!(guard < 64, "undo did not restore the initial state");
	}
	assert_eq!(
		backend.serialize_timeline().expect("snapshot"),
		initial,
		"the timeline serialisation must equal the post-import snapshot"
	);

	// An empty history reports NOTHING_TO_UNDO instead of pretending.
	let mut empty = SdkBackend::new();
	call(&mut empty, "project.open", json!({"fps": 30}));
	let err = execute(&mut empty, "edit.undo", json!({})).unwrap_err();
	assert_eq!(err.code, "NOTHING_TO_UNDO");
	assert_eq!(err.tool.as_deref(), Some("edit.undo"));

	let _ = std::fs::remove_file(&media_a);
	let _ = std::fs::remove_file(&media_b);
}

#[test]
fn a_rejected_edit_aborts_and_changes_nothing() {
	let _guard = engine_lock();
	let media = temp_media("abort");
	encode_solid_clip(&media, [0.2, 0.8, 0.2], 10, 10, 64);

	let mut backend = SdkBackend::new();
	let out = call(&mut backend, "project.open", json!({"fps": 30}));
	assert_eq!(out["created"], true);
	let out = call(
		&mut backend,
		"media.import_footage",
		json!({"paths": [media.display().to_string()]}),
	);
	let footage = out["footage"][0]["id"].as_str().unwrap().to_string();
	let duration = rat_of(&out["footage"][0]["duration"]);
	let track = call(&mut backend, "timeline.add_track", json!({"type": "video"}))["track"]
		.as_str()
		.unwrap()
		.to_string();

	// First placement: [0, 1).
	let out = call(
		&mut backend,
		"timeline.place_clip",
		json!({"track": track, "footage": footage, "in": 0}),
	);
	assert_eq!(out["out"], duration.to_json());
	let snapshot = backend.serialize_timeline().expect("snapshot");
	let history = backend.undo_index();

	// Second placement on top of it: rejected before the engine is touched.
	let err = execute(
		&mut backend,
		"timeline.place_clip",
		json!({"track": track, "footage": footage, "in": 0}),
	)
	.expect_err("an overlapping placement must be rejected");
	assert_eq!(err.code, "INVALID_PARAMS");
	assert_eq!(err.step.as_deref(), Some("invoke"));
	assert_eq!(err.txn.as_deref(), Some("aborted"), "the failure must abort");
	assert_eq!(err.tool.as_deref(), Some("timeline.place_clip"));

	// The document is byte-for-byte unchanged and no undo row was recorded.
	assert_eq!(backend.serialize_timeline().expect("snapshot"), snapshot);
	assert_eq!(
		backend.undo_index(),
		history,
		"an aborted call must not add an engine history row"
	);

	// A timecode rejection never even opens an undo group.
	let err = execute(
		&mut backend,
		"timeline.split_clip",
		json!({"clip": "clip-1", "time": 1.5}),
	)
	.unwrap_err();
	assert_eq!(err.code, "SCHEMA_VALIDATION_FAILED");
	assert_eq!(err.step.as_deref(), Some("validate"));
	assert!(err.txn.is_none());
	assert_eq!(backend.undo_index(), history);

	let _ = std::fs::remove_file(&media);
}

/// Minimal standard base64 (an independent decoder, so a bug in the crate's
/// encoder cannot make both sides agree on wrong bytes).
fn b64_decode(text: &str) -> Vec<u8> {
	const TABLE: &[u8; 64] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
	let clean: Vec<u8> = text.bytes().filter(|b| !b.is_ascii_whitespace()).collect();
	assert_eq!(clean.len() % 4, 0, "bad base64 length");
	let mut out = Vec::new();
	for chunk in clean.chunks(4) {
		let mut sextets = [0u32; 4];
		let mut pad = 0;
		for (index, &byte) in chunk.iter().enumerate() {
			if byte == b'=' {
				pad += 1;
				sextets[index] = 0;
			} else {
				sextets[index] = TABLE
					.iter()
					.position(|&candidate| candidate == byte)
					.expect("bad base64 character") as u32;
			}
		}
		let packed = (sextets[0] << 18) | (sextets[1] << 12) | (sextets[2] << 6) | sextets[3];
		out.push(((packed >> 16) & 0xff) as u8);
		if pad < 2 {
			out.push(((packed >> 8) & 0xff) as u8);
		}
		if pad < 1 {
			out.push((packed & 0xff) as u8);
		}
	}
	out
}
